={{ {
  model: $('Initialize Parameters').first().json.ollamaModel,
  messages: [
    { role: 'system', content: 'You are a Solution Architect producing integration artifacts. Output JSON with: integrationStyle (rest_only|events_only|hybrid), solutionMarkdown (starts with "# Solution Architecture:"), openapiYaml (OpenAPI 3.0 spec if REST), asyncapiYaml (AsyncAPI 2.0 spec if events), avroSchemasJson (Avro schemas object if events), cloudEventsMarkdown (Cloud Events documentation if events), sqlSchemaSql (PostgreSQL DDL). Include all relevant artifacts based on integrationStyle. No code fences anywhere.' },
    { role: 'user', content: 'PROJECT: ' + $json.projectName + '\nBRD: ' + JSON.stringify($json.artifacts.brd || {}).slice(0,6000) + '\nAPP_ARCH: ' + JSON.stringify($json.artifacts.application_arch || {}).slice(0,6000) + '\nDATA_ARCH: ' + JSON.stringify($json.artifacts.data_arch || {}).slice(0,4000) + '\nINFRA_ARCH: ' + JSON.stringify($json.artifacts.infrastructure_arch || {}).slice(0,4000) }
  ],
  stream: false,
  format: { type: 'object', required: ['integrationStyle','solutionMarkdown','sqlSchemaSql'], properties: { integrationStyle: { type: 'string', enum: ['rest_only','events_only','hybrid'] }, solutionMarkdown: { type: 'string' }, openapiYaml: { type: ['string','null'] }, asyncapiYaml: { type: ['string','null'] }, avroSchemasJson: { type: ['object','null'] }, cloudEventsMarkdown: { type: ['string','null'] }, sqlSchemaSql: { type: 'string' } } },
  options: { temperature: $('Initialize Parameters').first().json.ollamaTemperature, seed: $('Initialize Parameters').first().json.ollamaSeed }
} }}

